* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--jk-color-canvas);
  color: var(--jk-color-text);
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.45;
}

button { font: inherit; }

.intake-workspace {
  width: min(100%, 1365px);
  min-height: 900px;
  margin: 0 auto;
  padding: calc(var(--jk-space-4) * 1.5);
}

.workspace-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--jk-space-4);
  margin-bottom: var(--jk-space-4);
}

.eyebrow,
.section-label,
.meta-label {
  margin: 0 0 var(--jk-space-2);
  color: var(--jk-color-muted);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

h1, h2, h3, p { overflow-wrap: anywhere; }

h1 {
  margin: 0;
  font-size: clamp(1.5rem, 2.4vw, 2rem);
  line-height: 1.2;
}

h2 {
  margin: 0;
  font-size: 1.05rem;
  line-height: 1.3;
}

h3 {
  margin: 0;
  font-size: 0.95rem;
}

.subtitle {
  max-width: 720px;
  margin: var(--jk-space-2) 0 0;
  color: var(--jk-color-muted);
}

.progress {
  flex: 0 0 auto;
  padding: var(--jk-space-2) var(--jk-space-3);
  border: 1px solid var(--jk-color-border);
  border-radius: var(--jk-radius-control);
  background: var(--jk-color-surface);
  color: var(--jk-color-muted);
  font-size: 0.82rem;
  font-weight: 700;
}

.workspace-grid {
  display: grid;
  grid-template-columns: minmax(220px, 0.78fr) minmax(430px, 1.55fr) minmax(300px, 1fr);
  gap: var(--jk-space-4);
  align-items: start;
}

.panel {
  min-width: 0;
  border: 1px solid var(--jk-color-border);
  border-radius: var(--jk-radius-panel);
  background: var(--jk-color-surface);
}

.panel-header {
  padding: var(--jk-space-4);
  border-bottom: 1px solid var(--jk-color-border);
}

.panel-header p {
  margin: var(--jk-space-2) 0 0;
  color: var(--jk-color-muted);
  font-size: 0.86rem;
}

.queue-list {
  display: grid;
  gap: var(--jk-space-2);
  padding: var(--jk-space-3);
}

.queue-item {
  width: 100%;
  min-height: 72px;
  padding: var(--jk-space-3);
  border: 1px solid var(--jk-color-border);
  border-radius: var(--jk-radius-control);
  background: var(--jk-color-surface);
  color: var(--jk-color-text);
  text-align: left;
  cursor: pointer;
}

.queue-item:hover { border-color: var(--jk-color-focus); }

.queue-item[aria-current="true"] {
  border-color: var(--jk-color-focus);
  box-shadow: inset 4px 0 0 var(--jk-color-focus);
}

.queue-top,
.queue-bottom,
.packet-heading,
.handoff-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--jk-space-3);
}

.queue-name { font-weight: 750; }

.queue-id,
.queue-time {
  color: var(--jk-color-muted);
  font-size: 0.8rem;
  font-variant-numeric: tabular-nums;
}

.queue-bottom { margin-top: var(--jk-space-2); }

.status {
  display: inline-flex;
  align-items: center;
  min-height: 26px;
  padding: 0 var(--jk-space-2);
  border: 1px solid currentColor;
  border-radius: var(--jk-radius-control);
  font-size: 0.75rem;
  font-weight: 750;
}

.status-warning { color: var(--jk-color-warning); }
.status-risk { color: var(--jk-color-risk); }
.status-success { color: var(--jk-color-success); }

.packet-summary,
.readiness,
.policy,
.decision-section,
.handoff-section {
  padding: var(--jk-space-4);
}

.packet-summary,
.readiness,
.policy,
.decision-section {
  border-bottom: 1px solid var(--jk-color-border);
}

.packet-heading p {
  margin: var(--jk-space-2) 0 0;
  color: var(--jk-color-muted);
}

.packet-id {
  color: var(--jk-color-muted);
  font-size: 0.82rem;
  font-variant-numeric: tabular-nums;
}

.metadata {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--jk-space-3);
  margin: var(--jk-space-4) 0 0;
}

.metadata div {
  padding: var(--jk-space-3);
  border: 1px solid var(--jk-color-border);
  border-radius: var(--jk-radius-control);
}

.metadata dt { margin: 0; }
.metadata dd { margin: 0; font-weight: 700; }

.checklist {
  display: grid;
  gap: var(--jk-space-3);
  margin: var(--jk-space-3) 0 0;
  padding: 0;
  list-style: none;
}

.check-item {
  display: grid;
  grid-template-columns: 26px minmax(0, 1fr);
  gap: var(--jk-space-3);
  align-items: start;
}

.check-mark {
  display: grid;
  width: 26px;
  height: 26px;
  place-items: center;
  border: 1px solid currentColor;
  border-radius: 50%;
  font-weight: 800;
}

.check-complete .check-mark { color: var(--jk-color-success); }
.check-missing .check-mark { color: var(--jk-color-warning); }
.check-item p { margin: 2px 0 0; }
.check-item small { display: block; margin-top: 2px; color: var(--jk-color-muted); }

.policy {
  background: var(--jk-color-canvas);
}

.policy p { margin: var(--jk-space-2) 0 0; }

.decision-options {
  display: grid;
  gap: var(--jk-space-3);
  margin-top: var(--jk-space-3);
}

.decision-button {
  width: 100%;
  min-height: 48px;
  padding: var(--jk-space-3) var(--jk-space-4);
  border: 1px solid var(--jk-color-border);
  border-radius: var(--jk-radius-control);
  background: var(--jk-color-surface);
  color: var(--jk-color-text);
  text-align: left;
  font-weight: 750;
  cursor: pointer;
}

.decision-button:hover { border-color: var(--jk-color-focus); }

.decision-button[aria-pressed="true"] {
  border-color: var(--jk-color-warning);
  box-shadow: inset 4px 0 0 var(--jk-color-warning);
}

.decision-button small {
  display: block;
  margin-top: 3px;
  color: var(--jk-color-muted);
  font-weight: 500;
}

.handoff-card {
  margin-top: var(--jk-space-3);
  padding: var(--jk-space-4);
  border: 1px solid var(--jk-color-warning);
  border-radius: var(--jk-radius-panel);
  background: var(--jk-color-canvas);
}

.handoff-card p { margin: var(--jk-space-3) 0 0; }

.handoff-details {
  display: grid;
  gap: var(--jk-space-3);
  margin: var(--jk-space-4) 0;
}

.handoff-details div {
  padding-top: var(--jk-space-3);
  border-top: 1px solid var(--jk-color-border);
}

.handoff-details dt { margin: 0 0 2px; }
.handoff-details dd { margin: 0; }

.action-button {
  min-height: 44px;
  padding: var(--jk-space-3) var(--jk-space-4);
  border: 1px solid var(--jk-color-focus);
  border-radius: var(--jk-radius-control);
  background: var(--jk-color-focus);
  color: var(--jk-color-surface);
  font-weight: 800;
  cursor: pointer;
}

.action-button:disabled {
  border-color: var(--jk-color-disabled);
  background: var(--jk-color-disabled);
  cursor: not-allowed;
}

.action-button + small {
  display: block;
  margin-top: var(--jk-space-2);
  color: var(--jk-color-muted);
}

button:focus-visible {
  outline: 2px solid var(--jk-color-focus);
  outline-offset: 2px;
  box-shadow: var(--jk-focus-ring);
}

@media (max-width: 980px) {
  .workspace-grid { grid-template-columns: minmax(210px, 0.8fr) minmax(0, 1.6fr); }
  .handoff-panel { grid-column: 1 / -1; }
}

@media (max-width: 700px) {
  .intake-workspace { min-height: 100vh; padding: var(--jk-space-3); }
  .workspace-header { display: block; }
  .progress { display: inline-block; margin-top: var(--jk-space-3); }
  .workspace-grid { grid-template-columns: 1fr; }
  .handoff-panel { grid-column: auto; }
  .metadata { grid-template-columns: 1fr; }
}

@media (forced-colors: active) {
  .queue-item[aria-current="true"],
  .decision-button[aria-pressed="true"] { outline: 2px solid Highlight; }
}

